/** 
 * This step would determine the value of the action time
 * from a property on the work page.
*/

// obtain the value of the property from the workpage.
ClipboardPage slaPage = tools.findPage("ServiceLevelRecord");
String propertyName = slaPage.getString(".pyNextActionProperty");
String propertyValue = "";
try {
   propertyValue = myStepPage.getString(propertyName);
} catch (InvalidReferenceException e) {
   myStepPage.addMessage(e.getMessage());
}

// set the value for the pySLAAction as obtained form the property
ClipboardProperty pySLAAction = myStepPage.getProperty(".pySLAAction");
pySLAAction.setValue(propertyValue);

/** 
 * This step would determine the value of the goal time
 * from a property on the work page.
*/

// obtain the value of the property from the workpage.
ClipboardPage slaPage = tools.findPage("ServiceLevelRecord");
String propertyName = slaPage.getString(".pyGoalTimeProperty");
String propertyValue = "";
try {
   propertyValue = myStepPage.getString(propertyName);
} catch (InvalidReferenceException e) {
   myStepPage.addMessage(e.getMessage());
}

// set the value for the pySLAGoal as obtained from the property
ClipboardProperty pySLAGoal = myStepPage.getProperty(".pySLAGoal");
pySLAGoal.setValue(propertyValue);

/** 
 * This step would determine the value of the deadline time
 * from a property on the work page.
*/

// obtain the value of the property from the workpage.
ClipboardPage slaPage = tools.findPage("ServiceLevelRecord");
String propertyName = slaPage.getString(".pyDeadlineTimeProperty");
String propertyValue = "";
try {
   propertyValue = myStepPage.getString(propertyName);
} catch (InvalidReferenceException e) {
   myStepPage.addMessage(e.getMessage());
}

// set the value for the pySLADeadline as obtained from the property
ClipboardProperty pySLADeadline = myStepPage.getProperty(".pySLADeadline");
pySLADeadline.setValue(propertyValue);

// Reference the OverallSLA flow, if present
ClipboardProperty thisFlowRef = myStepPage.getIfPresent(".pxFlow(OverallSLA)");
if (thisFlowRef == null)
	return false;

// Find the assignment's key
ClipboardPage thisFlowPage = thisFlowRef.getPageValue();
String pxAssignmentKey = thisFlowPage.getString("pxAssignmentKey");
if (pxAssignmentKey.equals(""))
	return false;

// Open the assignment
ClipboardPage assignPage = null;
try {
	assignPage = tools.getDatabase().open(pxAssignmentKey, false);
} catch (DatabaseException e) {
	myStepPage.addMessage(e.getMessage());
}

if (assignPage == null)
	return false;

// Reset the assignment's goal time
String goalTime = myStepPage.getString(".pySLAGoal");
assignPage.putString("pxGoalTime", goalTime);

// Reset the assignment's deadline time
String deadlineTime = myStepPage.getString(".pySLADeadline");
assignPage.putString("pxDeadlineTime", deadlineTime);

// now let's see if these new properties are in the past or not.  If they
// aren't, we need to blank out pxGoalExecute and pxDeadlineExecute to allow
// them to happen again
if (pega_rules_default.isInThePast(goalTime) == false)
    assignPage.putString("pxGoalExecute", "");

if (pega_rules_default.isInThePast(deadlineTime) == false)
    assignPage.putString("pxDeadlineExecute", "");

// set the service level name
String slaName = myStepPage.getString(".pySLAName");
assignPage.putString("pxServiceLevelName", slaName);

// Bug-85572: update late properties on assignpage
ClipboardPage slaPage = tools.findPage("ServiceLevelRecord");
if (slaPage.getInteger("pyMaxLateEvents") > 0) {
	if(slaPage.getIfPresent("pyEscalations") != null) {
		ClipboardPage latePage = slaPage.getProperty("pyEscalations").getPageValue("Late");
		if (latePage.getInteger("pyDays") > 0 || latePage.getInteger("pyHours") > 0
				|| latePage.getInteger("pyMinutes") > 0 || latePage.getInteger("pySeconds") > 0 ) {
			assignPage.putString("pxLateMaximum", slaPage.getString("pyMaxLateEvents"));
			assignPage.putString("pyLateDefaultDays", latePage.getString("pyDays"));
			assignPage.putString("pyLateDefaultHours", latePage.getString("pyHours"));
			assignPage.putString("pyLateDefaultMinutes", latePage.getString("pyMinutes"));
			assignPage.putString("pyLateDefaultSeconds", latePage.getString("pySeconds"));
			assignPage.putString("pyLateInBusinessDays", latePage.getString("pyInBusinessDays"));
		}
	}
	else if (slaPage.getInteger("pyLateDefaultDays") > 0 || slaPage.getInteger("pyLateDefaultHours") > 0 
			|| slaPage.getInteger("pyLateDefaultMinutes") > 0 || slaPage.getInteger("pyLateDefaultSeconds") > 0) {
		assignPage.putString("pxLateMaximum", slaPage.getString("pyMaxLateEvents"));
		assignPage.putString("pyLateDefaultDays", slaPage.getString("pyLateDefaultDays"));
		assignPage.putString("pyLateDefaultHours", slaPage.getString("pyLateDefaultHours"));
		assignPage.putString("pyLateDefaultMinutes", slaPage.getString("pyLateDefaultMinutes"));
		assignPage.putString("pyLateDefaultSeconds", slaPage.getString("pyLateDefaultSeconds"));
		assignPage.putString("pyLateInBusinessDays", slaPage.getString("pyLateInBusinessDays"));
	}
}


try {
	PRQueueManager QM = tools.getThread().getQueueManager();
	boolean createNewQueuePage = false;

	// First dequeue the sla queue item for update
	String itemid = assignPage.getString(".pxRefQueueKey");
	if (itemid.equals(""))
		createNewQueuePage = true;
	else {
		ClipboardPage queuePage = QM.dequeueForUpdate(itemid);
		if (queuePage != null)
		{
			// Now update it with the new time
			queuePage.putString("pxEvent","Goal");
			queuePage.putString("pyMinimumDateTimeForProcessing", assignPage.getString(".pxGoalTime"));
			QM.updateDeferred(queuePage,true);

			if(queuePage.getString(".pyItemStatus").equalsIgnoreCase("Broken-Process"))
				QM.repairDeferred(itemid);
		}
		else
			createNewQueuePage = true;
	}

	if (createNewQueuePage)
	{
		ClipboardPage newQueuePage = tools.createPage("System-Queue-ServiceLevel", "");
		newQueuePage.putString("pyAgentName", "Pega-ProCom:ServiceLevelEvents");
		newQueuePage.putString("pxAssignmentClass" , assignPage.getString(".pxObjClass"));
		newQueuePage.putString("pxAssignmentHandle" , assignPage.getString(".pzInsKey"));
		newQueuePage.putString("pxEvent" , "Goal");
		newQueuePage.putString("pxTaskName" , assignPage.getString(".pxTaskName") );
		newQueuePage.putString("pyMinimumDateTimeForProcessing" , assignPage.getString(".pxGoalTime") );
		newQueuePage.putString("pyItemStatus" , "Scheduled");
		newQueuePage.putString("pyAccessGroup" , tools.findPage("pxThread").getString(".pxCurrentAccessGroup") );
		newQueuePage.putString("pyUseApplications" , "true");
		newQueuePage.putString("pxAssignmentCreateDateTime", assignPage.getString(".pxCreateDateTime"));
		String newItemid = QM.enqueueDeferred(newQueuePage);
		assignPage.putString("pxRefQueueKey", newItemid);
	}

	// Now save the assignment
	tools.getDatabase().saveDeferred(assignPage, false, false);
} catch (DatabaseException e) {
	myStepPage.addMessage(e.getMessage());
}

nextBlock = "PR";
